import {cleanTeam,missingCookies,rankTeams,checkRune,validateBackup} from './logic.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>{try{const u=new URL(url);if(u.protocol!=='https:')return '';return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}catch{return ''}};
const KEY='nekomata-crumble-v1';
let local={version:1,owned:[],favorites:[],teams:[],notes:{}};
try{const raw=localStorage.getItem(KEY);if(raw)local=validateBackup(JSON.parse(raw));}catch{ /* keep defaults; do not destroy a malformed previous backup */ }
let db,generated={videos:[],teams:[],runeNotes:[],state:'not_configured'},page='stage',query='',onlyOwned=false,onlyFavorite=false,arena='arena',daily='全部',dexOwned=false,selectedCookie='',toastTimer;
const info={stage:['TEAM PLANNER','推圖陣容','比對持有名單，找到能先嘗試的隊伍。'],guild:['GUILD RAID','公會討伐戰','把增益目標、重試條件和隊伍筆記一起保存。'],arena:['ARENA PLANNER','競技場陣容','一般與熱熱鬧鬧分開看，避免混用不同規則。'],daily:['DAILY DUNGEONS','每日副本','依副本切換參考配置，保留自己實際能過的版本。'],dex:['COOKIE INDEX / SUGAR RUNES','角色與加工糖','勾選持有、查詢糖符文候選，再決定是否投入重洗。'],updates:['SOURCES / CHANGELOG','來源與更新','每個建議都能回到原始資料；影片解析與人工資料分開保留。']};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(local));return true}catch{toast('儲存失敗：請匯出設定，避免關閉後遺失。');return false}}
function allTeams(){const auto=(generated.teams||[]).flatMap(t=>{try{return [{...cleanTeam(t),...t,status:'auto'}]}catch{return []}});return [...db.teams,...auto,...local.teams];}
function stat(label,value,note){return `<div class="stat"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
function missing(t){return missingCookies(t,local.owned)}
function teamCard(t){const own=local.owned.length?`${t.cookies.length-missing(t).length}/${t.cookies.length} 已持有`:'持有名單尚未設定';const fav=local.favorites.includes(t.id);return `<article class="team-card"><div class="team-top"><span class="badge ${t.status==='custom'?'green':t.status==='auto'?'orange':''}">${t.status==='custom'?'我的配置':t.status==='auto'?'影片解析・待實測':'社群參考'}${t.subtype?' / '+esc(t.subtype):''}</span><button class="favorite ${fav?'on':''}" data-fav="${esc(t.id)}" aria-label="${fav?'取消收藏':'收藏'} ${esc(t.title)}" aria-pressed="${fav}">${fav?'★':'☆'}</button></div><h2>${esc(t.title)}</h2><p class="description">${esc(t.note)}</p><div class="roster">${t.cookies.map(n=>`<button class="cookie-chip ${local.owned.includes(n)?'owned':''}" data-cookie="${esc(n)}" title="查看 ${esc(n)} 的糖符文">${esc(n)}</button>`).join('')}</div><div class="pets">${(t.pets||[]).map(n=>`<span>${esc(n)}</span>`).join('')}</div>${t.benefits?.length?`<p class="muted">福利：${t.benefits.map(esc).join(' · ')}</p>`:''}<div class="team-meta"><span>${esc(own)}</span><span>來源 ${esc(t.sourceDate||'未標日期')}</span></div>${local.owned.length&&missing(t).length?`<details><summary>查看缺少的 ${missing(t).length} 名餅乾</summary><p>${missing(t).map(esc).join('、')}</p><p>持有比對不包含星級、寵物、養成與綜效，不能視為強度分數。</p></details>`:''}<div class="team-actions">${t.sourceUrl?link(t.sourceUrl,t.sourceLabel||'原始來源'):''}<button data-copy="${esc(t.id)}">複製名單</button><button data-clone="${esc(t.id)}">另存我的配置</button>${t.status==='custom'?`<button data-remove="${esc(t.id)}">移除配置</button>`:''}</div><details><summary>我的實測筆記</summary><textarea class="notes-input" rows="3" maxlength="2000" data-note="${esc(t.id)}" aria-label="${esc(t.title)}實測筆記" placeholder="關卡、星級、通關結果或下次調整…">${esc(local.notes[t.id]||'')}</textarea></details></article>`}
function renderTeams(){
 const mode=page==='arena'?arena:page;
 const base=allTeams().filter(t=>t.mode===mode&&(page!=='daily'||daily==='全部'||t.subtype===daily));
 let list=base.filter(t=>(!onlyFavorite||local.favorites.includes(t.id))&&(!onlyOwned||!missing(t).length)&&[t.title,t.note,...t.cookies,...(t.pets||[])].join(' ').toLowerCase().includes(query.toLowerCase()));
 if(local.owned.length)list=rankTeams(list,local.owned);
 let sub='';if(page==='arena')sub=`<div class="subtabs">${[['arena','一般競技場'],['chaos','熱熱鬧鬧競技場']].map(([k,v])=>`<button data-arena="${k}" class="${arena===k?'active':''}">${v}</button>`).join('')}</div>`;
 if(page==='daily')sub=`<div class="subtabs">${['全部','經驗值','錢幣','麵團','研究石','符文結晶'].map(k=>`<button data-daily="${k}" class="${daily===k?'active':''}">${k}</button>`).join('')}</div>`;
 $('#content').innerHTML=`${sub}<div class="stats">${stat('參考與自訂配置',base.length,'依目前模式統計')}${stat('我的持有餅乾',local.owned.length,'到角色圖鑑勾選')}${stat('此模式收藏',base.filter(t=>local.favorites.includes(t.id)).length,'只保存在此瀏覽器')}</div><div class="toolbar"><input type="search" id="search" value="${esc(query)}" placeholder="搜尋隊伍、餅乾或寵物" aria-label="搜尋配置"><label><input type="checkbox" id="owned-filter" ${onlyOwned?'checked':''} ${local.owned.length?'':'disabled'}>無缺角</label><label><input type="checkbox" id="favorite-filter" ${onlyFavorite?'checked':''}>只看收藏</label><button class="primary" id="new-team">＋ 我的配置</button></div>${mode==='chaos'?'<div class="notice">此模式尚無核實來源。你可以先保存自己的配置；未將一般競技場建議自動套用於此。</div>':''}<p class="section-label">${list.length} 組配置 · ${local.owned.length?'依缺角數排序':'先勾選持有餅乾，即可比對缺角'}</p><div class="team-grid">${list.map(teamCard).join('')}</div>${!list.length?'<div class="empty"><h2>目前沒有符合的配置</h2><p>可調整篩選，或新增自己的隊伍。</p></div>':''}`;
 $('#search').addEventListener('input',e=>{query=e.target.value;const pos=e.target.selectionStart;renderTeams();$('#search').focus();$('#search').setSelectionRange(pos,pos)});
 $('#owned-filter').addEventListener('change',e=>{onlyOwned=e.target.checked;renderTeams()});$('#favorite-filter').addEventListener('change',e=>{onlyFavorite=e.target.checked;renderTeams()});$('#new-team').onclick=()=>openEditor();
}
function renderDex(){
 const cookies=db.cookies.filter(c=>(!dexOwned||local.owned.includes(c.name))&&(c.name+ ' '+c.stats.join(' ')).toLowerCase().includes(query.toLowerCase()));
 $('#content').innerHTML=`<div class="notice">初版收錄 ${db.cookies.length} 名已出現在配置中的餅乾，非完整圖鑑。糖符文建議依來源模式列出；尚無來源者不套通用配法。</div><div class="toolbar"><input id="dex-search" type="search" value="${esc(query)}" placeholder="搜尋餅乾或詞條" aria-label="搜尋餅乾"><label><input type="checkbox" id="dex-owned" ${dexOwned?'checked':''}>只看持有</label></div><div class="split"><section><div class="dex-grid">${cookies.map(c=>`<article class="cookie-card ${selectedCookie===c.name?'selected':''}"><span class="badge">${c.stats.length?'有糖符文來源':'待補建議'}</span><h2>${esc(c.name)}</h2><label><input type="checkbox" data-owned="${esc(c.name)}" ${local.owned.includes(c.name)?'checked':''}>已持有</label><button data-rune="${esc(c.name)}">查看加工建議 →</button></article>`).join('')}</div>${!cookies.length?'<p class="empty">找不到符合的餅乾。</p>':''}</section><aside class="panel" id="rune-panel"></aside></div>`;
 $('#dex-search').oninput=e=>{query=e.target.value;const p=e.target.selectionStart;renderDex();$('#dex-search').focus();$('#dex-search').setSelectionRange(p,p)};$('#dex-owned').onchange=e=>{dexOwned=e.target.checked;renderDex()};renderRune();
}
function renderRune(){
 const cookie=db.cookies.find(c=>c.name===selectedCookie)||db.cookies[0];selectedCookie=cookie.name;
 const attrs=['攻擊力增幅','技能增幅提升','技能加速提升','暴擊率','暴擊傷害','專注率增加','傷害減少','體力','防禦力','其他'];
 const latest=(generated.runeNotes||[]).filter(n=>n.cookie===cookie.name);
 $('#rune-panel').innerHTML=`<p class="eyebrow">SUGAR RUNE CHECK</p><h2>${esc(cookie.name)}</h2><p class="muted">${esc(cookie.runeNote)}</p>${cookie.stats.length?`<p>參考候選：${cookie.stats.map(s=>`<span class="badge green">${esc(s)}</span>`).join(' ')}</p>${link(cookie.runeSource,'查看此配置來源')}`:'<p class="badge orange">尚無已整理的建議</p>'}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h2>現有詞條檢查</h2><p class="muted">填入你要檢查的詞條；留白不計。鎖定只作提醒，不會替你操作遊戲。</p>${[0,1,2].map(i=>`<div class="rune-choice"><select class="rune-stat" aria-label="詞條 ${i+1}"><option value="">選擇詞條</option>${attrs.map(x=>`<option>${x}</option>`).join('')}</select><label><input class="rune-lock" type="checkbox">已鎖定</label></div>`).join('')}<button class="primary" id="check-rune">比對候選詞條</button><div id="rune-result" class="result-box"><strong>先保留可用，再評估重洗</strong><p>本工具不提供未核實的洗煉機率與數值門檻。</p></div>${latest.length?`<h2 style="margin-top:22px">影片補充</h2>${latest.map(n=>`<p class="muted">${esc(n.note)}<br>${link(n.sourceUrl,'影片時間位置')}</p>`).join('')}`:''}`;
 $('#check-rune').onclick=()=>{const stats=[...document.querySelectorAll('.rune-stat')];const locks=[...document.querySelectorAll('.rune-lock')];const r=checkRune(cookie.stats,stats.map((s,i)=>({stat:s.value,locked:locks[i].checked})));$('#rune-result').innerHTML=`<strong>${esc(r.title)}</strong><p>${esc(r.detail)}</p>`};
}
function renderUpdates(){
 const state=generated.state==='ok'?'已完成檢查':generated.state==='error'?'上次檢查有錯誤':'尚未啟用 API 排程';
 const urls=[...new Set(db.teams.map(t=>t.sourceUrl))];
 $('#content').innerHTML=`<div class="stats">${stat('影片資料來源','蹦蹦林','@ponponlin')}${stat('每日檢查時間','10:17','台灣時間；Actions 可能延遲')}${stat('更新狀態',state,generated.lastCheckedAt?new Date(generated.lastCheckedAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):'待設定 Secrets 與啟用開關')}</div><div class="split"><section class="panel"><h2>新片 → 網站</h2><div class="step"><b>01</b>讀取指定頻道的公開上傳清單</div><div class="step"><b>02</b>依遊戲名稱篩選，再用影片內容確認遊戲</div><div class="step"><b>03</b>擷取陣容、模式、糖符文與時間戳</div><div class="step"><b>04</b>通過格式與來源檢查後，新增影片參考版本</div><p class="muted">原有人工配置不被覆寫。內容不完整、模式不明或新角色名稱未核實的項目保留待確認；API 失敗不會標成處理成功。</p><p>${link('https://www.youtube.com/channel/UC4O0Bsolr3brLF1jdo9v-jg','PonPonLin 蹦蹦林')}</p><p class="muted">頻道 ID：<code>UC4O0Bsolr3brLF1jdo9v-jg</code></p></section><section class="panel"><h2>影片更新紀錄</h2><div class="source-list">${(generated.videos||[]).length?(generated.videos||[]).map(v=>`<article>${link(v.url,v.title)}<p>${esc(v.summary||v.state)}</p><small>${esc(v.publishedAt)} · ${esc(v.state==='published'?'已加入參考':v.state==='not_game'?'非本遊戲，略過':'待確認')}</small></article>`).join(''):'<p class="muted">尚未執行影片分析。初版隊伍來自下方社群來源，沒有假稱已讀取蹦蹦林影片。</p>'}</div></section></div><section class="panel" style="margin-top:20px"><h2>初版資料來源</h2><p class="muted">僅整理少量配隊索引與簡短重點，完整解說請回原作者網站。參考隊伍不保證適合每個帳號。</p><div class="source-list">${urls.map(u=>`<article>${link(u,db.teams.find(t=>t.sourceUrl===u).title)}<br><small>社群來源 · 核對日 ${esc(db.checkedAt)}</small></article>`).join('')}</div></section>`;
}
function render(){
 page=location.hash.slice(1)||'stage';if(!info[page])page='stage';
 document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const [e,t,i]=info[page];$('#eyebrow').textContent=e;$('#title').textContent=t;$('#intro').textContent=i;
 if(page==='dex')renderDex();else if(page==='updates')renderUpdates();else renderTeams();
}
function openEditor(team){$('#team-form').reset();$('#form-error').textContent='';$('#team-name').value=team?team.title+'（我的版本）':'';$('#team-mode').value=team?.mode||(page==='arena'?arena:['stage','guild','daily'].includes(page)?page:'stage');$('#team-subtype').value=team?.subtype||'';$('#team-cookies').value=team?.cookies.join('\n')||'';$('#team-pets').value=team?.pets.join('\n')||'';$('#team-note').value=team?.note||'';$('#editor').showModal()}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||!db)return;
 if(b.dataset.arena){arena=b.dataset.arena;renderTeams()}
 if(b.dataset.daily){daily=b.dataset.daily;renderTeams()}
 if(b.dataset.fav){const id=b.dataset.fav;local.favorites=local.favorites.includes(id)?local.favorites.filter(x=>x!==id):[...local.favorites,id];save();renderTeams()}
 if(b.dataset.cookie||b.dataset.rune){selectedCookie=b.dataset.cookie||b.dataset.rune;query='';if(page!=='dex')location.hash='dex';else renderRune()}
 if(b.dataset.clone)openEditor(allTeams().find(t=>t.id===b.dataset.clone));
 if(b.dataset.copy){const t=allTeams().find(t=>t.id===b.dataset.copy);const text=`${t.title}\n${t.cookies.join('、')}\n寵物：${t.pets.join('、')}\n${t.note}\n${t.sourceUrl||'我的配置'}`;try{await navigator.clipboard.writeText(text);toast('隊伍名單已複製')}catch{toast('剪貼簿被阻擋，請從隊伍卡手動複製。')}}
 if(b.dataset.remove){local.teams=local.teams.filter(t=>t.id!==b.dataset.remove);local.favorites=local.favorites.filter(id=>id!==b.dataset.remove);save();renderTeams();toast('配置已移除')}
});
document.addEventListener('change',e=>{if(e.target.dataset.owned){const n=e.target.dataset.owned;local.owned=e.target.checked?[...new Set([...local.owned,n])]:local.owned.filter(x=>x!==n);save()}if(e.target.dataset.note){local.notes[e.target.dataset.note]=e.target.value.slice(0,2000);save();toast('筆記已儲存')}});
$('#close-editor').onclick=()=>$('#editor').close();
$('#team-form').onsubmit=e=>{e.preventDefault();try{const split=s=>s.split(/\n|、|,/).map(x=>x.trim()).filter(Boolean);const t=cleanTeam({id:'custom-'+crypto.randomUUID(),title:$('#team-name').value,mode:$('#team-mode').value,subtype:$('#team-mode').value==='daily'?$('#team-subtype').value:'',cookies:split($('#team-cookies').value),pets:split($('#team-pets').value),note:$('#team-note').value,sourceDate:new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'})});local.teams.push(t);save();$('#editor').close();if(t.mode==='chaos')arena='chaos';else if(t.mode==='arena')arena='arena';query='';onlyOwned=false;onlyFavorite=false;const dest=t.mode==='chaos'?'arena':t.mode;if(page===dest)render();else location.hash=dest;toast('已儲存我的配置')}catch(err){$('#form-error').textContent=err.message}};
$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(local,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='cookie-lab-settings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已匯出設定')};
$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2_000_000)throw Error('檔案超過 2 MB');const data=validateBackup(JSON.parse(await f.text()));local=data;save();render();toast('已載入設定檔')}catch(err){toast('匯入失敗：'+err.message)}e.target.value=''};
window.addEventListener('hashchange',()=>{query='';onlyOwned=false;onlyFavorite=false;render()});
try{const r=await fetch('./data/catalog.json');if(!r.ok)throw Error('資料讀取失敗');db=await r.json();try{const r2=await fetch('./data/generated.json');if(r2.ok)generated=await r2.json()}catch{}render()}catch(err){$('#content').innerHTML=`<div class="empty"><h2>無法讀取配置資料</h2><p>${esc(err.message)}，請透過網站網址開啟並重新整理。</p></div>`}
